from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    dirs4=[(-1,0),(1,0),(0,-1),(0,1)]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); comp=[]; exterior=False
        while q:
          y,x=q.popleft(); comp.append((y,x))
          if y==0 or x==0 or y==h-1 or x==w-1: exterior=True
          for dy,dx in dirs4:
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in seen:
              seen.add((yy,xx)); q.append((yy,xx))
        for y,x in comp:
          if exterior:
            if any(0<=y+dy<h and 0<=x+dx<w and grid[y+dy][x+dx]==1 for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx):
              out[y][x]=2
          else:
            if any(0<=y+dy<h and 0<=x+dx<w and grid[y+dy][x+dx]==1 for dy,dx in dirs4):
              out[y][x]=3
    return out

