def transform2(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    d4=[(-1,0),(1,0),(0,-1),(0,1)]
    # connected zero components, interior vs exterior
    zseen=set(); interior=[]; ext=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 or (r,c) in zseen: continue
        q=deque([(r,c)]); zseen.add((r,c)); comp=[]; edge=False
        while q:
          y,x=q.popleft(); comp.append((y,x)); edge |= y==0 or x==0 or y==h-1 or x==w-1
          for dy,dx in d4:
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in zseen:
              zseen.add((yy,xx)); q.append((yy,xx))
        if edge: ext.update(comp)
        else: interior.append(comp)
    if not interior: return out
    # components of ones
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); comp=[]
        while q:
          y,x=q.popleft(); comp.append((y,x))
          for dy,dx in d4:
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and (yy,xx) not in seen:
              seen.add((yy,xx)); q.append((yy,xx))
        comp_set=set(comp)
        enclosed_touch=False
        for zcomp in interior:
          if any((y+dy,x+dx) in comp_set for y,x in zcomp for dy,dx in d4):
            enclosed_touch=True; break
        if not enclosed_touch: continue
        for y,x in comp:
          for dy in (-1,0,1):
            for dx in (-1,0,1):
              yy,xx=y+dy,x+dx
              if (dy or dx) and 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) in ext:
                out[yy][xx]=2
    for zcomp in interior:
      for y,x in zcomp:
        if any(0<=y+dy<h and 0<=x+dx<w and grid[y+dy][x+dx]==1 for dy,dx in d4): out[y][x]=3
    return out

